open(P+'/task-558aa788.py','w').write('''def transform(grid):
    h, w = len(grid), len(grid[0])
    cons = {}
    p = None
    for pp in range(1, 31):
        cons = {}
        ok = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    s = (c - r) % pp
                    if s in cons and cons[s] != v:
                        ok = False
                        break
                    cons[s] = v
            if not ok:
                break
        if ok and len(cons) == pp:
            p = pp
            seq = [cons[i] for i in range(pp)]
            break
    if p is None:
        return grid
    return [[seq[(c - r) % p] for c in range(w)] for r in range(h)]
''')
